// src/sync/appliers/common.ts
async function verifyTenantEntity(tx, table, id, ctxPharmacyId, notFoundCode, entityName) {
  return verifyTenantEntities(tx, table, [id], ctxPharmacyId, notFoundCode, entityName);
}
async function verifyTenantEntities(tx, table, ids, ctxPharmacyId, notFoundCode, entityName) {
  const uniqueIds = Array.from(new Set(ids.filter(Boolean)));
  if (uniqueIds.length === 0) return;
  const localRows = await tx.select({ id: table.id }).from(table).where(and(eq(table.pharmacyId, ctxPharmacyId), inArray(table.id, uniqueIds)));
  const localSet = new Set(localRows.map((r) => String(r.id)));
  const missingIds = uniqueIds.filter((id) => !localSet.has(id));
  if (missingIds.length === 0) return;
  const otherRows = await tx.select({ id: table.id }).from(table).where(inArray(table.id, missingIds));
  const firstOther = otherRows[0];
  if (firstOther) {
    const crossTenantId = String(firstOther.id);
    throw new SyncRejectedError(
      "CROSS_TENANT_REFERENCE",
      `Referenced ${entityName} ${crossTenantId} belongs to another pharmacy tenant`
    );
  }
  const firstMissing = missingIds[0] || "unknown";
  throw new SyncRetryLaterError(
    notFoundCode,
    `Referenced ${entityName} ${firstMissing} not found for pharmacy ${ctxPharmacyId}`
  );
}

