    const line2 = invoice.lines[i];
    if (!line2.batchId) {
      throw new SyncRejectedError(
        "MISSING_BATCH_COST",
        `${docLabel}: invoice line #${i + 1} (${line2.id}) is missing batchId required for COGS`
      );
    }
