  const pageRows = hasMore ? rawRows.slice(0, limit) : rawRows;
  const changes = pageRows.map((r) => ({
    seq: Number(r.seq),
    entity: r.entity,
    entityId: r.entityId,
    op: r.op,
    data: r.data || {},
    createdAt: r.createdAt
  }));
