// src/auth/user-auth.ts
function requirePermission(permission) {
  const handler2 = async function(request, reply) {
    const authHeader = request.headers.authorization;
    if (!authHeader || !authHeader.startsWith("Bearer ")) {
      reply.status(401).send({
        statusCode: 401,
        error: "Unauthorized",
        message: "Missing or invalid Authorization header"
      });
      return;
    }
    const token = authHeader.slice(7).trim();
    let payload;
    try {
      payload = verifyUserToken(token);
    } catch {
      reply.status(401).send({
        statusCode: 401,
        error: "Unauthorized",
        message: "Invalid or expired session token"
      });
      return;
    }
    const db = request.server.db || getDb();
    if (payload.jti) {
      if (isUserTokenRevoked(payload.jti)) {
        reply.status(401).send({
          statusCode: 401,
          error: "Unauthorized",
          message: "User token has been revoked"
        });
        return;
      }
      try {
        const [revoked] = await db.select({ jti: revokedTokens.jti }).from(revokedTokens).where(eq(revokedTokens.jti, payload.jti)).limit(1);
        if (revoked) {
          revokeUserToken(payload.jti);
          reply.status(401).send({
            statusCode: 401,
            error: "Unauthorized",
            message: "User token has been revoked"
          });
          return;
        }
      } catch {
      }
    }
    try {
      const [user] = await db.select({
        id: users.id,
        pharmacyId: users.pharmacyId,
        role: users.role,
        name: users.name,
        isActive: users.isActive
      }).from(users).where(and(eq(users.id, payload.userId), eq(users.pharmacyId, payload.pharmacyId))).limit(1);
      if (!user) {
        reply.status(401).send({
          statusCode: 401,
          error: "Unauthorized",
          message: "User account not found or tenant mismatch"
        });
        return;
      }
      if (!user.isActive) {
        reply.status(403).send({
          statusCode: 403,
          error: "Forbidden",
          message: "User account is inactive"
        });
        return;
      }
      const role = user.role;
      if (!hasPermission(role, permission)) {
        reply.status(403).send({
          statusCode: 403,
          error: "Forbidden",
          message: `Insufficient permissions: user role '${role}' lacks permission '${permission}'`
        });
        return;
      }
      request.userContext = {
        userId: user.id,
        pharmacyId: user.pharmacyId,
        role,
        name: user.name,
        ...payload.jti ? { jti: payload.jti } : {}
      };
    } catch (err) {
      request.log.error({ err }, "Error during user auth verification");
      reply.status(500).send({
        statusCode: 500,
        error: "Internal Server Error",
        message: "Database error verifying user session"
      });
    }
  };
  handler2.requiredPermission = permission;
  return handler2;
}

