// src/routes/reports.ts
var SalesQuerySchema = external_exports.object({
  startDate: external_exports.string().regex(/^\d{4}-\d{2}-\d{2}/, "Invalid startDate format").optional(),
  endDate: external_exports.string().regex(/^\d{4}-\d{2}-\d{2}/, "Invalid endDate format").optional(),
  branchId: external_exports.string().uuid("Invalid branchId format").optional(),
  cashierUserId: external_exports.string().uuid("Invalid cashierUserId format").optional()
});
var StockQuerySchema = external_exports.object({
  branchId: external_exports.string().uuid("Invalid branchId format").optional()
});
var BatchRecallQuerySchema = external_exports.object({
  batchNo: external_exports.string().min(1, "batchNo query parameter is required")
});
var reportRoutes = async (fastify) => {
  fastify.get(
    "/sales",
    { preHandler: [requirePermission("reports.sales.view")] },
    async (request, reply) => {
      const parsedQuery = SalesQuerySchema.safeParse(request.query);
      if (!parsedQuery.success) {
        return reply.status(400).send({
          statusCode: 400,
          error: "Bad Request",
          message: parsedQuery.error.issues[0]?.message || "Invalid query parameters"
        });
      }
      const userContext = request.userContext;
      const db = request.server.db || getDb();
      const { startDate, endDate, branchId, cashierUserId } = parsedQuery.data;
      if (branchId) {
        const [branch] = await db.select({ id: branches.id }).from(branches).where(and(eq(branches.id, branchId), eq(branches.pharmacyId, userContext.pharmacyId))).limit(1);
        if (!branch) {
          return reply.status(404).send({ statusCode: 404, message: "Branch not found or belongs to another pharmacy" });
        }
      }
      if (cashierUserId) {
        const [user] = await db.select({ id: users.id }).from(users).where(and(eq(users.id, cashierUserId), eq(users.pharmacyId, userContext.pharmacyId))).limit(1);
        if (!user) {
          return reply.status(404).send({
            statusCode: 404,
            message: "Cashier user not found or belongs to another pharmacy"
          });
        }
      }
      const result = await getSalesReport(db, {
        pharmacyId: userContext.pharmacyId,
        startDate,
        endDate,
        branchId,
        cashierUserId
      });
      return reply.status(200).send(result);
    }
  );
  fastify.get(
    "/stock-and-expiry",
    { preHandler: [requirePermission("reports.stock.view")] },
    async (request, reply) => {
      const parsedQuery = StockQuerySchema.safeParse(request.query);
      if (!parsedQuery.success) {
        return reply.status(400).send({
          statusCode: 400,
          error: "Bad Request",
          message: parsedQuery.error.issues[0]?.message || "Invalid query parameters"
        });
      }
      const userContext = request.userContext;
      const db = request.server.db || getDb();
      const { branchId } = parsedQuery.data;
      if (branchId) {
        const [branch] = await db.select({ id: branches.id }).from(branches).where(and(eq(branches.id, branchId), eq(branches.pharmacyId, userContext.pharmacyId))).limit(1);
        if (!branch) {
          return reply.status(404).send({ statusCode: 404, message: "Branch not found or belongs to another pharmacy" });
        }
      }
      const result = await getStockAndExpiryReport(db, userContext.pharmacyId, branchId);
      return reply.status(200).send({ items: result });
    }
  );
  fastify.get(
    "/profit-per-batch",
    { preHandler: [requirePermission("reports.profit.view")] },
    async (request, reply) => {
      const userContext = request.userContext;
      const db = request.server.db || getDb();
      const result = await getProfitPerBatchReport(db, userContext.pharmacyId);
      return reply.status(200).send({ items: result });
    }
  );
  fastify.get(
    "/supplier-ledger",
    { preHandler: [requirePermission("reports.supplier_ledger.view")] },
    async (request, reply) => {
      const userContext = request.userContext;
      const db = request.server.db || getDb();
      const result = await getSupplierLedgerReport(db, userContext.pharmacyId);
      return reply.status(200).send({ items: result });
    }
  );
  fastify.get(
    "/batch-recall",
    { preHandler: [requirePermission("reports.stock.view")] },
    async (request, reply) => {
      const parsedQuery = BatchRecallQuerySchema.safeParse(request.query);
      if (!parsedQuery.success) {
        return reply.status(400).send({
          statusCode: 400,
          error: "Bad Request",
          message: parsedQuery.error.issues[0]?.message || "batchNo query parameter is required"
        });
      }
      const userContext = request.userContext;
      const db = request.server.db || getDb();
      const { batchNo } = parsedQuery.data;
      const matchingBatches = await db.select({
        batchId: batches.id,
        batchNo: batches.batchNo,
        expiryDate: batches.expiryDate,
        costPaisa: batches.costPaisa,
        mrpPaisa: batches.mrpPaisa,
        productId: products.id,
        brandName: products.brandName,
        genericName: products.genericName
      }).from(batches).innerJoin(products, eq(batches.productId, products.id)).where(and(eq(batches.pharmacyId, userContext.pharmacyId), eq(batches.batchNo, batchNo)));
      const batchIds = matchingBatches.map((b) => b.batchId);
      let affectedInvoices = [];
      if (batchIds.length > 0) {
        affectedInvoices = await db.select({
          invoiceId: invoices.id,
          invoiceNumber: invoices.invoiceNumber,
          invoiceDate: invoices.createdAt,
          quantity: invoiceLines.quantity,
          unitPricePaisa: invoiceLines.unitPricePaisa,
          lineTotalPaisa: invoiceLines.lineTotalPaisa,
          customerId: invoices.customerId,
          customerName: customers.name,
          customerPhone: customers.phone
        }).from(invoiceLines).innerJoin(invoices, eq(invoiceLines.invoiceId, invoices.id)).leftJoin(customers, eq(invoices.customerId, customers.id)).where(
          and(
            eq(invoiceLines.pharmacyId, userContext.pharmacyId),
            eq(invoices.pharmacyId, userContext.pharmacyId),
            inArray(invoiceLines.batchId, batchIds)
          )
        ).orderBy(desc(invoices.createdAt));
      }
      const totalUnitsSold = affectedInvoices.reduce((sum, row) => sum + row.quantity, 0);
      return reply.status(200).send({
        batchNo,
        matchingBatches,
        totalUnitsSold,
        affectedInvoices
      });
    }
  );
};

// src/routes/admin.ts
var IdParamSchema = external_exports.object({
  id: external_exports.string().uuid("Invalid ID format")
});
