async function executeYearEndClosing(db, input2) {
  const executeInTx = async (tx) => {
    const deterministicSourceId = getYearEndClosingSourceId(input2.pharmacyId, input2.fiscalYear);
    const [existing] = await tx.select({ id: journalEntries.id }).from(journalEntries).where(
      and(
        eq(journalEntries.pharmacyId, input2.pharmacyId),
        eq(journalEntries.sourceType, "year_end_closing"),
        eq(journalEntries.sourceId, deterministicSourceId)
      )
    ).limit(1);
    if (existing) {
      return {
        journalEntryId: existing.id,
        netProfitPaisa: 0,
        linesCount: 0
      };
    }
    const startDate = `${input2.fiscalYear}-01-01`;
    const endDate = input2.closingDate;
    const [reAcct] = await tx.select({ id: accounts.id, code: accounts.code, name: accounts.name }).from(accounts).where(and(eq(accounts.pharmacyId, input2.pharmacyId), eq(accounts.code, "3100")));
    if (!reAcct) {
      throw new Error("Retained Earnings account (3100) not found in Chart of Accounts");
    }
    const plBalances = await tx.select({
      accountId: journalLines.accountId,
      accountCode: accounts.code,
      accountName: accounts.name,
      accountType: accounts.type,
      totalDebit: sql`COALESCE(SUM(${journalLines.debitPaisa}), 0)`,
      totalCredit: sql`COALESCE(SUM(${journalLines.creditPaisa}), 0)`
    }).from(journalLines).innerJoin(accounts, eq(journalLines.accountId, accounts.id)).innerJoin(journalEntries, eq(journalLines.entryId, journalEntries.id)).where(
      and(
        eq(journalLines.pharmacyId, input2.pharmacyId),
        gte(journalEntries.entryDate, startDate),
        lte(journalEntries.entryDate, endDate),
        eq(journalEntries.status, "posted")
      )
    ).groupBy(journalLines.accountId, accounts.code, accounts.name, accounts.type);
    const plRows = plBalances.filter((b) => {
      return b.accountType === "revenue" || b.accountType === "expense" || b.accountCode.startsWith("4") || b.accountCode.startsWith("5") || b.accountCode.startsWith("6");
    });
    const lines = [];
    let sumDebits = 0;
    let sumCredits = 0;
    for (const row of plRows) {
      const totalDebit = Number(row.totalDebit || 0);
      const totalCredit = Number(row.totalCredit || 0);
      const netDebit = totalDebit - totalCredit;
      if (netDebit > 0) {
        lines.push({
          accountId: row.accountId,
          debitPaisa: 0,
          creditPaisa: netDebit,
          memo: `Year-end zeroing of ${row.accountCode} - ${row.accountName}`
        });
        sumCredits += netDebit;
      } else if (netDebit < 0) {
        const creditBal = -netDebit;
        lines.push({
          accountId: row.accountId,
          debitPaisa: creditBal,
          creditPaisa: 0,
          memo: `Year-end zeroing of ${row.accountCode} - ${row.accountName}`
        });
        sumDebits += creditBal;
      }
    }
    const netProfitPaisa = sumDebits - sumCredits;
    if (netProfitPaisa > 0) {
      lines.push({
        accountId: reAcct.id,
        debitPaisa: 0,
        creditPaisa: netProfitPaisa,
        memo: `Net profit transfer to Retained Earnings for FY${input2.fiscalYear}`
      });
    } else if (netProfitPaisa < 0) {
      lines.push({
        accountId: reAcct.id,
        debitPaisa: -netProfitPaisa,
        creditPaisa: 0,
        memo: `Net loss transfer to Retained Earnings for FY${input2.fiscalYear}`
      });
    }
    if (lines.length === 0) {
      return {
        journalEntryId: null,
        netProfitPaisa: 0,
        linesCount: 0
      };
    }
    const entry = await postJournalEntry(tx, {
      pharmacyId: input2.pharmacyId,
      entryDate: input2.closingDate,
      sourceType: "year_end_closing",
      sourceId: deterministicSourceId,
      memo: input2.memo || `FY${input2.fiscalYear} Year-End Closing Entry to Retained Earnings`,
      createdBy: input2.actorUserId,
      lines
    });
    return {
      journalEntryId: entry.id,
      netProfitPaisa,
      linesCount: lines.length
    };
  };
  const transactionalDb = db;
  if (typeof transactionalDb.transaction === "function") {
    return await transactionalDb.transaction(executeInTx);
  }
  return await executeInTx(db);
}

// src/ledger/queries.ts
async function accountLedger(db, accountId, from, to, pharmacyId) {
  const accountConds = [eq(accounts.id, accountId)];
  if (pharmacyId) {
    accountConds.push(eq(accounts.pharmacyId, pharmacyId));
  }
  const [account] = await db.select().from(accounts).where(and(...accountConds)).limit(1);
  if (!account) {
    throw new Error("Account not found or belongs to another pharmacy");
  }
  const resolvedPharmacyId = account.pharmacyId;
  const [openingRow] = await db.select({
    debitBefore: sql`COALESCE(SUM(${journalLines.debitPaisa}), 0)`,
    creditBefore: sql`COALESCE(SUM(${journalLines.creditPaisa}), 0)`
  }).from(journalLines).innerJoin(
    journalEntries,
    and(
      eq(journalLines.entryId, journalEntries.id),
      eq(journalEntries.pharmacyId, resolvedPharmacyId)
    )
  ).where(
    and(
      eq(journalLines.pharmacyId, resolvedPharmacyId),
      eq(journalLines.accountId, accountId),
      lt(journalEntries.entryDate, from)
    )
  );
  const openingBalancePaisa = Number(openingRow?.debitBefore ?? 0) - Number(openingRow?.creditBefore ?? 0);
  const rawLines = await db.select({
    lineId: journalLines.id,
    entryId: journalEntries.id,
    entryNo: journalEntries.entryNo,
    entryDate: journalEntries.entryDate,
    sourceType: journalEntries.sourceType,
    sourceId: journalEntries.sourceId,
    entryMemo: journalEntries.memo,
    lineMemo: journalLines.memo,
    branchId: journalLines.branchId,
    partyType: journalLines.partyType,
    partyId: journalLines.partyId,
    debitPaisa: journalLines.debitPaisa,
    creditPaisa: journalLines.creditPaisa
  }).from(journalLines).innerJoin(
    journalEntries,
    and(
      eq(journalLines.entryId, journalEntries.id),
      eq(journalEntries.pharmacyId, resolvedPharmacyId)
    )
  ).where(
    and(
      eq(journalLines.pharmacyId, resolvedPharmacyId),
      eq(journalLines.accountId, accountId),
      gte(journalEntries.entryDate, from),
      lte(journalEntries.entryDate, to)
    )
  ).orderBy(asc(journalEntries.entryDate), asc(journalEntries.entryNo), asc(journalLines.id));
  let runningBalancePaisa = openingBalancePaisa;
  let totalDebitPaisa = 0;
  let totalCreditPaisa = 0;
  const lines = rawLines.map((row) => {
    const debit = Number(row.debitPaisa);
    const credit = Number(row.creditPaisa);
    totalDebitPaisa += debit;
    totalCreditPaisa += credit;
    runningBalancePaisa += debit - credit;
    return {
      lineId: row.lineId,
      entryId: row.entryId,
      entryNo: Number(row.entryNo),
      entryDate: row.entryDate,
      sourceType: row.sourceType,
      sourceId: row.sourceId,
      entryMemo: row.entryMemo,
      lineMemo: row.lineMemo,
      branchId: row.branchId,
      partyType: row.partyType,
      partyId: row.partyId,
      debitPaisa: debit,
      creditPaisa: credit,
      runningBalancePaisa
    };
  });
  return {
    accountId: account.id,
    pharmacyId: resolvedPharmacyId,
    code: account.code,
    name: account.name,
    type: account.type,
    from,
    to,
    openingBalancePaisa,
    totalDebitPaisa,
    totalCreditPaisa,
    closingBalancePaisa: runningBalancePaisa,
    lines
  };
}

