function calculateDaysDifference(asOfDateStr, entryDateStr) {
  const asOf = new Date(asOfDateStr);
  const entry = new Date(entryDateStr);
  const diffTime = asOf.getTime() - entry.getTime();
  return Math.floor(diffTime / (1e3 * 60 * 60 * 24));
}
function classifyAgingBucket(days) {
  if (days <= 0) return "current";
  if (days <= 30) return "days1to30";
  if (days <= 60) return "days31to60";
  if (days <= 90) return "days61to90";
  return "days90Plus";
}
async function getArAccountId(db, pharmacyId) {
  const [mapped] = await db.select({ accountId: pharmacyAccountMappings.accountId }).from(pharmacyAccountMappings).where(
    and(
      eq(pharmacyAccountMappings.pharmacyId, pharmacyId),
      eq(pharmacyAccountMappings.role, "ar")
    )
  ).limit(1);
  if (mapped?.accountId) {
    return mapped.accountId;
  }
  const [acct] = await db.select({ id: accounts.id }).from(accounts).where(and(eq(accounts.pharmacyId, pharmacyId), eq(accounts.code, "1100"))).limit(1);
  if (!acct) {
    throw new Error(`Accounts Receivable account (code 1100) not found for pharmacy ${pharmacyId}`);
  }
  return acct.id;
}
