var ReminderSchema2 = external_exports.object({
  partyType: external_exports.literal("supplier"),
  partyId: external_exports.string().uuid(),
  channel: external_exports.enum(["sms", "whatsapp", "phone", "email", "in_person"]).default("phone"),
  recipient: external_exports.string().nullable().optional(),
  message: external_exports.string().nullable().optional(),
  amountPaisa: external_exports.number().int().min(0).default(0),
  daysOverdue: external_exports.number().int().min(0).default(0),
  documentId: external_exports.string().uuid().nullable().optional()
});
function calculateDaysDifference2(asOfDateStr, entryDateStr) {
  const asOf = new Date(asOfDateStr);
  const entry = new Date(entryDateStr);
  const diffTime = asOf.getTime() - entry.getTime();
  return Math.floor(diffTime / (1e3 * 60 * 60 * 24));
}
function classifyAgingBucket2(days) {
  if (days <= 0) return "current";
  if (days <= 30) return "days1to30";
  if (days <= 60) return "days31to60";
  if (days <= 90) return "days61to90";
  return "days90Plus";
}
async function getApAccountId(db, pharmacyId) {
  const [mapped] = await db.select({ accountId: pharmacyAccountMappings.accountId }).from(pharmacyAccountMappings).where(
    and(
      eq(pharmacyAccountMappings.pharmacyId, pharmacyId),
      eq(pharmacyAccountMappings.role, "ap")
    )
  ).limit(1);
  if (mapped?.accountId) {
    return mapped.accountId;
  }
  const [acct] = await db.select({ id: accounts.id }).from(accounts).where(and(eq(accounts.pharmacyId, pharmacyId), eq(accounts.code, "2000"))).limit(1);
  if (!acct) {
    throw new Error(`Accounts Payable account (code 2000) not found for pharmacy ${pharmacyId}`);
  }
  return acct.id;
}
