function addDaysToDate(dateStr, days) {
  const [y, m, d] = dateStr.split("-").map(Number);
  const date6 = new Date(Date.UTC(y, m - 1, d));
  date6.setUTCDate(date6.getUTCDate() + days);
  return toKarachiBusinessDate2(date6);
}
function addYearsToDate(dateStr, years) {
  const [y, m, d] = dateStr.split("-").map(Number);
  const targetYear = y + years;
  return `${targetYear}-${String(m).padStart(2, "0")}-${String(d).padStart(2, "0")}`;
}
